def bars(g, bg):
    out=[]
    for i,row in enumerate(g):
        j=0
        while j<len(row):
            if row[j]!=bg:
                k=j
                while k<len(row) and row[k]==row[j]: k+=1
                if k-j>1 or True: out.append((i,j,k-j,row[j]))
                j=k
            else: j+=1
    return out

def diag_cells(h,w):
    return sorted(((i,j) for i in range(h) for j in range(w)), key=lambda p:(p[0]+p[1], p[1]))

def transform(g):
    bg=g[0][0]
    bs=sorted(bars(g,bg), key=lambda b:(-b[3],))
    cols=sorted({b[3] for b in bs}, reverse=True)
    h=len(cols); w=len(cols)+1
    out=[[0]*w for _ in range(h)]
    for b,cell in zip(sorted(bs,key=lambda b:-b[3]), diag_cells(h,w)):
        out[cell[0]][cell[1]]=b[3]
    return out

